//! Integration tests for the edits → WorkOrder admission bridge
//! (`ggen_bridge` module `edits_bridge`). Chicago style: real files under
//! a real temp tree, real sha256 commitments over real bytes, assertions
//! on final state (admitted order, journaled chain) — no mocks. The
//! `SymbolGraph` seam is backed by the REAL ggen-scip index
//! (`ScipGraph`) over real generated bytes — including the repo's own
//! `crates/ggen-cli/src/generated_commands.rs` (the R80-11 UNKNOWN →
//! PARTIAL_ALIVE witness). [`edits_bridge::VectorGraph`] is retained as
//! the disclosed deterministic test-only fallback fixture.

use ggen_sjira::edits_bridge::{
    empty_sha256, run_admission_loop, ScipGraph, SymbolGraph, BridgeJournal, BridgeRefusal,
    EditBatch, FileEdit, TreeContext, VectorGraph,
};

/// Real temp tree with drop cleanup (Cargo.toml is outside lane
/// ownership, so no `tempfile` dev-dependency is added).
struct TempTree {
    path: std::path::PathBuf,
}

impl TempTree {
    fn new(tag: &str) -> Self {
        let path = std::env::temp_dir().join(format!(
            "ggen-sjira-ebtest-{}-{}",
            tag,
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&path);
        std::fs::create_dir_all(&path).expect("temp tree created");
        TempTree { path }
    }

    fn write(&self, rel: &str, bytes: &[u8]) {
        let abs = self.path.join(rel);
        if let Some(parent) = abs.parent() {
            std::fs::create_dir_all(parent).expect("parent dirs created");
        }
        std::fs::write(abs, bytes).expect("file written");
    }
}

impl Drop for TempTree {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.path);
    }
}

fn sha256_hex(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    let mut h = Sha256::new();
    h.update(bytes);
    h.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

fn edit(path: &str, before: Option<&[u8]>, after: &[u8]) -> FileEdit {
    FileEdit {
        path: path.to_string(),
        before_bytes: before.map(|b| b.to_vec()),
        after_bytes: after.to_vec(),
        before_sha256: sha256_hex(before.unwrap_or(&[])),
        after_sha256: sha256_hex(after),
    }
}

fn batch(description: &str, edits: Vec<FileEdit>) -> EditBatch {
    EditBatch {
        description: description.to_string(),
        edits,
        verification_command: "cargo test -p ggen-sjira edits_bridge".to_string(),
        mutation_description: "revert the edit; the acceptance test must fail".to_string(),
    }
}

fn ctx(tree: &TempTree) -> TreeContext {
    TreeContext {
        tree_root: tree.path.clone(),
        repository: "owner/repo".to_string(),
        base_sha: "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".to_string(),
        protected_paths: vec![],
    }
}

#[test]
fn edit_batch_becomes_admitted_work_order_and_journaled_transition() {
    let tree = TempTree::new("happy");
    tree.write("src/lib.rs", b"fn main() {}\n");
    let b = batch(
        "bridge the edits surface",
        vec![edit("src/lib.rs", Some(b"fn main() {}\n"), b"fn main() { ok(); }\n")],
    );
    let mut journal = BridgeJournal::new();
    let receipt =
        run_admission_loop(&b, &ctx(&tree), None, &mut journal).expect("loop runs");

    // The proposal carried path-scope evidence and UNKNOWN standing.
    let proposed = receipt.proposed.expect("proposal present");
    let order = &proposed.work_order;
    assert_eq!(order.standing, ggen_sjira::Standing::Unknown);
    assert_eq!(order.subject, "src/lib.rs");
    assert_eq!(order.repository, "owner/repo");
    assert_eq!(order.base_sha, "a".repeat(40));
    assert_eq!(
        order.acceptance,
        vec!["cargo test -p ggen-sjira edits_bridge".to_string()]
    );
    assert_eq!(
        order.falsifiers,
        vec!["revert the edit; the acceptance test must fail".to_string()]
    );
    assert_eq!(order.required_evidence, vec!["path:src/lib.rs".to_string()]);

    // Admitted at UNKNOWN standing, authority NONE.
    let admitted = receipt.admitted.expect("admitted");
    assert_eq!(admitted.authority, "NONE");
    assert_eq!(admitted.work_order, *order);

    // The transition is journaled with the batch digest bound.
    let last = journal.entries().last().expect("journaled");
    assert_eq!(last.decision, "ADMITTED");
    assert_eq!(last.work_order_digest, admitted.work_order_digest);
    assert_eq!(last.blast_radius_digest, Some(proposed.evidence.batch_digest.clone()));
    assert_eq!(receipt.journal_head, journal.head());
    journal.verify_chain().expect("chain intact");
}

#[test]
fn new_file_edit_admits_with_empty_before_commitment() {
    let tree = TempTree::new("newfile");
    // No file on disk; before-commitment is the empty image.
    let b = batch("add a module", vec![edit("src/new.rs", None, b"pub mod new;\n")]);
    let mut journal = BridgeJournal::new();
    let receipt = run_admission_loop(&b, &ctx(&tree), None, &mut journal).expect("loop runs");
    assert!(receipt.admitted.is_some());
    let order = &receipt.proposed.as_ref().expect("proposed").work_order;
    assert_eq!(
        order.required_evidence,
        vec!["path:src/new.rs".to_string()]
    );
    assert_eq!(journal.entries().last().expect("journaled").decision, "ADMITTED");
    assert_ne!(empty_sha256(), sha256_hex(b"pub mod new;\n"));
    journal.verify_chain().expect("chain intact");
}

#[test]
fn protected_path_batch_refuses_and_journals_nothing_at_admission() {
    let tree = TempTree::new("protected");
    tree.write("src/protected.rs", b"secret\n");
    let mut c = ctx(&tree);
    c.protected_paths = vec!["src/protected.rs".to_string()];
    let b = batch(
        "touch the protected surface",
        vec![edit("src/protected.rs", Some(b"secret\n"), b"hacked\n")],
    );
    let mut journal = BridgeJournal::new();
    let err = run_admission_loop(&b, &c, None, &mut journal).expect_err("refused");
    match &err {
        BridgeRefusal::ProtectedPath { path } => assert_eq!(path, "src/protected.rs"),
        other => panic!("expected ProtectedPath, got {other:?}"),
    }
    // Refusal text carries the remediation clause.
    let text = err.to_string();
    assert!(text.contains("remediation"), "remediation present in: {text}");
    // Refused at the evidence boundary: nothing journaled, chain genesis.
    assert!(journal.is_empty());
    assert_eq!(journal.head(), BridgeJournal::GENESIS);
}

#[test]
fn tampered_evidence_refuses_before_proposal() {
    let tree = TempTree::new("tamper");
    tree.write("src/x.rs", b"original\n");
    let b = batch(
        "edit a file whose tree state then moves",
        vec![edit("src/x.rs", Some(b"original\n"), b"changed\n")],
    );
    // Tamper: the tree moves after capture.
    tree.write("src/x.rs", b"mutated on disk after capture\n");
    let mut journal = BridgeJournal::new();
    let err = run_admission_loop(&b, &ctx(&tree), None, &mut journal).expect_err("refused");
    match &err {
        BridgeRefusal::TamperedEvidence { path } => assert_eq!(path, "src/x.rs"),
        other => panic!("expected TamperedEvidence, got {other:?}"),
    }
    assert!(err.to_string().contains("re-capture"));
    assert!(journal.is_empty(), "tamper refuses before any journaling");
}

#[test]
fn absent_file_tamper_refuses() {
    let tree = TempTree::new("absent-tamper");
    // Commitment says the file exists; disk has nothing.
    let b = batch(
        "edit a file the tree no longer has",
        vec![edit("src/gone.rs", Some(b"was here\n"), b"now changed\n")],
    );
    let mut journal = BridgeJournal::new();
    let err = run_admission_loop(&b, &ctx(&tree), None, &mut journal).expect_err("refused");
    assert!(matches!(err, BridgeRefusal::TamperedEvidence { .. }));
    assert!(journal.is_empty());
}

#[test]
fn blast_radius_handle_attaches_required_evidence() {
    let tree = TempTree::new("radius");
    tree.write("src/a.rs", b"pub fn f() {}\n");
    let graph = VectorGraph {
        edges: vec![
            ("src/a.rs::f".to_string(), "src/b.rs::g".to_string()),
            ("src/b.rs::g".to_string(), "src/c.rs::h".to_string()),
        ],
    };
    let b = batch(
        "edit with blast radius",
        vec![edit("src/a.rs", Some(b"pub fn f() {}\n"), b"pub fn f() -> u32 { 1 }\n")],
    );
    let mut journal = BridgeJournal::new();
    let receipt = run_admission_loop(&b, &ctx(&tree), Some(&graph), &mut journal)
        .expect("loop runs");
    let order = &receipt.proposed.as_ref().expect("proposed").work_order;
    assert_eq!(
        order.required_evidence,
        vec![
            "path:src/a.rs".to_string(),
            "blast-radius:src/a.rs::f".to_string(),
            "blast-radius:src/b.rs::g".to_string(),
            "blast-radius:src/c.rs::h".to_string(),
        ]
    );
    // Journaled transition binds the radius digest.
    let last = journal.entries().last().expect("journaled");
    assert!(last.blast_radius_digest.is_some());
    assert_eq!(last.decision, "ADMITTED");
    journal.verify_chain().expect("chain intact");
}

#[test]
fn illegal_hand_built_transition_refuses() {
    let mut journal = BridgeJournal::new();
    let forged = ggen_sjira::edits_bridge::JournaledOutcome {
        work_order_digest: "sha256:1111111111111111111111111111111111111111111111111111111111111111".to_string(),
        decision: "ADMITTED".to_string(),
        detail: "authority=NONE".to_string(),
        blast_radius_digest: None,
        prev_hash: BridgeJournal::GENESIS.to_string(),
        hash: "forged".to_string(),
    };
    let err = journal
        .append_sealed(forged)
        .err()
        .expect("illegal transition refused");
    assert!(matches!(err, BridgeRefusal::IllegalTransition { .. }));
    assert!(err.to_string().contains("remediation"));
    assert!(journal.is_empty(), "forged record not appended");
    journal.verify_chain().expect("chain still genesis-intact");
}

#[test]
fn empty_batch_refuses() {
    let tree = TempTree::new("empty");
    let mut journal = BridgeJournal::new();
    let err = run_admission_loop(&batch("nothing", vec![]), &ctx(&tree), None, &mut journal)
        .expect_err("refused");
    assert!(matches!(err, BridgeRefusal::EmptyBatch));
    assert!(journal.is_empty());
}

/// Repo root (tests live at crates/ggen-sjira/tests/).
fn repo_root() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
}

/// The repo's real generated file, copied byte-exact into a temp root
/// laid out like the workspace (`crates/ggen-cli/`), so ggen-scip's real
/// emitter indexes REAL generated bytes deterministically.
fn temp_root_with_real_generated_file(tag: &str) -> TempTree {
    let tree = TempTree::new(tag);
    let real = repo_root()
        .join("crates/ggen-cli/src/generated_commands.rs")
        .exists();
    assert!(real, "real generated_commands.rs present in repo");
    let bytes = std::fs::read(
        repo_root().join("crates/ggen-cli/src/generated_commands.rs"),
    )
    .expect("real generated file read");
    tree.write(
        "crates/ggen-cli/Cargo.toml",
        b"[package]\nname = \"ggen-cli\"\n",
    );
    tree.write("crates/ggen-cli/src/generated_commands.rs", &bytes);
    tree
}

#[test]
fn scip_index_over_real_generated_file_backs_blast_radius() {
    let tree = temp_root_with_real_generated_file("scip-real");
    // Real ggen-scip emitter over real generated bytes.
    let index = ggen_scip::emit::build_index(&tree.path).expect("index built");
    let graph = ScipGraph::from_index(index);

    let doc_path = "crates/ggen-cli/src/generated_commands.rs";
    // open_root court: real emit to disk, then open through the query API.
    ggen_scip::emit::emit(&tree.path).expect("emit writes .ggen/scip.json");
    let opened = ScipGraph::open_root(&tree.path).expect("open_root reads it");
    assert!(
        !opened.blast_radius(doc_path).is_empty(),
        "open_root-backed graph answers the seam"
    );

    // The radius is real: it contains the file's actual defined symbol(s)
    // (COMMANDS_REFERENCE) as the seed and reaches referenced symbols.
    let radius = graph.blast_radius(doc_path);
    assert!(
        radius
            .iter()
            .any(|s| s.contains("generated_commands.COMMANDS_REFERENCE")),
        "seed symbol COMMANDS_REFERENCE in radius, got {radius:?}"
    );

    // Full loop with the SCIP-backed graph: blast-radius evidence is
    // attached to the proposed WorkOrder and admitted.
    let file_bytes = std::fs::read(tree.path.join(doc_path)).expect("bytes");
    let b = batch(
        "edit the real generated commands reference",
        vec![edit(
            doc_path,
            Some(file_bytes.as_slice()),
            b"// edited generated surface\n",
        )],
    );
    let mut journal = BridgeJournal::new();
    let receipt = run_admission_loop(&b, &ctx(&tree), Some(&graph), &mut journal)
        .expect("loop runs");
    let order = &receipt.proposed.as_ref().expect("proposed").work_order;
    assert_eq!(order.subject, doc_path);
    assert!(
        order
            .required_evidence
            .iter()
            .any(|e| e.starts_with("blast-radius:ggen ggen-cli generated_commands.")),
        "SCIP-derived blast-radius evidence attached, got {:?}",
        order.required_evidence
    );
    assert!(receipt.admitted.is_some());
    assert_eq!(journal.entries().last().expect("journaled").decision, "ADMITTED");
    journal.verify_chain().expect("chain intact");
}

#[test]
fn real_repo_scip_witness_promotes_symbol_graph_standing() {
    // The R80-11 promotion witness: the REAL ggen-scip emitter indexed
    // over the REAL repo root (no temp layout), and the real repo file
    // carries a SCIP definition + nonempty radius through ScipGraph.
    let root = repo_root();
    let index = ggen_scip::emit::build_index(&root).expect("repo index built");

    let doc_path = "crates/ggen-cli/src/generated_commands.rs";
    let doc = graph_index_doc(&index, doc_path).expect("doc indexed");
    let has_def = doc.occurrences.iter().any(|o| {
        o.roles & ggen_scip::ROLE_DEFINITION != 0
            && o.symbol.contains("generated_commands.")
    });
    assert!(has_def, "COMMANDS_REFERENCE definition occurrence present");
    drop(doc);

    // The SCIP-backed graph over the same real index answers the seam.
    let graph = ScipGraph::from_index(index);
    assert!(graph.document_count() > 0, "generated docs indexed");
    let radius = graph.blast_radius(doc_path);
    assert!(
        !radius.is_empty(),
        "real repo SCIP witness: nonempty blast radius"
    );
    // Query API also answers over the same index (cross-check).
    let q = ggen_scip::query::Query::from_index(
        ggen_scip::emit::build_index(&root).expect("rebuild for query cross-check"),
    );
    assert!(q.symbol_count() > 0);
    assert!(q.def("ggen ggen-cli-lib generated_commands.COMMANDS_REFERENCE").is_some());
}

/// Find an indexed document by path (test helper over the raw index).
fn graph_index_doc<'a>(
    index: &'a ggen_scip::Index,
    path: &str,
) -> Option<&'a ggen_scip::Document> {
    index.documents.iter().find(|d| d.path == path)
}

#[test]
fn tamper_at_depth_breaks_verify_chain() {
    let tree = TempTree::new("chaindepth");
    tree.write("src/one.rs", b"one\n");
    tree.write("src/two.rs", b"two\n");
    let mut journal = BridgeJournal::new();
    for (i, (path, before)) in [("src/one.rs", &b"one\n"[..]), ("src/two.rs", b"two\n")]
        .into_iter()
        .enumerate()
    {
        let b = batch(
            &format!("batch {i}"),
            vec![edit(path, Some(before), b"edited\n")],
        );
        run_admission_loop(&b, &ctx(&tree), None, &mut journal).expect("loop runs");
    }
    assert_eq!(journal.len(), 2);
    journal.verify_chain().expect("intact before tamper");
    // Tamper at depth 0: mutate the first journaled record's body.
    journal.entries_mut()[0].detail = "tampered".to_string();
    let err = journal.verify_chain().expect_err("tamper detected");
    assert!(
        matches!(err, BridgeRefusal::IllegalTransition { .. }),
        "got {err}"
    );
}
